26		public static final int JWT_AUTHENTICATION = Ordered.HIGHEST_PRECEDENCE + 25;
27	
28		public static final int JWT_NONCE = Ordered.HIGHEST_PRECEDENCE + 28;
29	
30		public static final int HMAC_AUTHENTICATION = Ordered.HIGHEST_PRECEDENCE + 29;
31	
32		public static final int CONTEXT_HEADER_INJECTION = Ordered.HIGHEST_PRECEDENCE + 30;
