        @DisplayName("TTL is set on nonce keys via SETNX")
        void nonceKeysHaveTtl() {
            String testKey = "platform:gateway:jwt:nonce:ttl-test:test-nonce";
            redisTemplate.opsForValue().setIfAbsent(testKey, "1",
                    java.time.Duration.ofSeconds(60)).block();

