@DisplayName("Gateway starter integration tests")
class GatewayStarterIntegrationTest {

    @Container
    static GenericContainer<?> redisContainer = new GenericContainer<>(
            DockerImageName.parse("redis:7-alpine"))
            .withExposedPorts(6379);

    @DynamicPropertySource
    static void redisProperties(DynamicPropertyRegistry registry) {
        registry.add("spring.data.redis.host", redisContainer::getHost);
        registry.add("spring.data.redis.port", () -> redisContainer.getMappedPort(6379));
    }

    @Autowired
    private ApplicationContext context;

    @Autowired
    private ReactiveRedisTemplate<String, String> redisTemplate;

    @SpringBootApplication
    static class TestApp {
    }

    // ---------- startup verification ----------

    @Nested
    @DisplayName("Context startup")
    class ContextStartup {

        @Test
        @DisplayName("application context loads successfully with gateway starter")
        void contextLoads() {
            assertThat(context).isNotNull();
            assertThat(context.getStartupDate()).isPositive();
        }

        @Test
        @DisplayName("ReactiveRedisTemplate bean is created and connected")
        void redisTemplateIsAvailable() {
            assertThat(redisTemplate).isNotNull();
            assertThat(redisTemplate.getConnectionFactory()).isNotNull();
        }

        @Test
        @DisplayName("Redis container is running and reachable")
        void redisIsReachable() {
            Mono<String> ping = redisTemplate.opsForValue().getAndSet("__test_ping__", "pong");
            StepVerifier.create(ping)
                    .expectNextCount(1)
                    .verifyComplete();

            redisTemplate.delete("__test_ping__").block();
        }
    }

