        @DisplayName("default auth mode is NONE for integration test (none/jwt/hmac/jwt-or-hmac all supported)")
        void defaultModeIsNone() {
            assertThat(policyResolver.getDefaultAuthMode()).isEqualTo(AuthMode.NONE);
        }
    }
}

package com.maritime.platform.gateway.integration;

import com.maritime.platform.gateway.security.GatewaySecurityProperties;
import com.maritime.platform.gateway.security.RouteSecurityPolicyResolver;
import com.maritime.platform.gateway.security.AuthMode;
import com.maritime.platform.gateway.security.RouteSecurityPolicy;
import com.maritime.platform.gateway.security.hmac.DefaultAppCredentialResolver;
import com.maritime.platform.gateway.security.hmac.HmacNonceValidator;
import com.maritime.platform.gateway.security.jwt.GatewayAuthErrorCode;
import com.maritime.platform.gateway.security.jwt.JwtAuthenticationException;
import com.maritime.platform.gateway.security.jwt.JwtStateValidator;
import com.maritime.platform.gateway.security.nonce.JwtNonceValidator;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.context.ApplicationContext;
import org.springframework.data.redis.core.ReactiveRedisTemplate;
import org.springframework.test.context.DynamicPropertyRegistry;
import org.springframework.test.context.DynamicPropertySource;
import org.testcontainers.containers.GenericContainer;
import org.testcontainers.junit.jupiter.Container;
import org.testcontainers.junit.jupiter.Testcontainers;
import org.testcontainers.utility.DockerImageName;

import reactor.core.publisher.Mono;
import reactor.test.StepVerifier;

import java.util.Map;

import static org.assertj.core.api.Assertions.assertThat;

@SpringBootTest(
        classes = GatewayStarterIntegrationTest.TestApp.class,
        webEnvironment = SpringBootTest.WebEnvironment.NONE,
        properties = {
                "maritime.gateway.security.default-auth-mode=none",
                "maritime.gateway.security.jwt.enabled=true",
                "maritime.gateway.security.jwt.secret=test-secret-with-minimum-length-256-bits!!",
                "maritime.gateway.security.jwt.issuer=test-issuer",
                "maritime.gateway.security.jwt.validation.require-session=true",
                "maritime.gateway.security.jwt.validation.check-blacklist=true",
                "maritime.gateway.security.jwt.validation.check-user-enabled=true",
                "maritime.gateway.security.jwt.validation.user-enabled-disabled-value=DISABLED",
                "maritime.gateway.security.jwt.nonce.enabled=true",
                "maritime.gateway.security.hmac.enabled=true",
                "maritime.gateway.security.hmac.credentials.apps[0].app-key=test-app",
                "maritime.gateway.security.hmac.credentials.apps[0].app-secret=test-secret",
                "maritime.gateway.security.hmac.credentials.apps[0].app-code=test-app-code",
                "spring.cloud.gateway.enabled=false",
                "spring.main.web-application-type=none"
        })
@Testcontainers
@DisplayName("Gateway starter integration tests")
class GatewayStarterIntegrationTest {

    @Container
    static GenericContainer<?> redisContainer = new GenericContainer<>(
            DockerImageName.parse("redis:7-alpine"))
            .withExposedPorts(6379);

    @DynamicPropertySource
    static void redisProperties(DynamicPropertyRegistry registry) {
        registry.add("spring.data.redis.host", redisContainer::getHost);
        registry.add("spring.data.redis.port", () -> redisContainer.getMappedPort(6379));
    }

    @SpringBootApplication
    static class TestApp {
    }

    // ---------- startup verification ----------

    @Nested
    @DisplayName("Context startup")
    class ContextStartup {

        @Autowired
        private ApplicationContext context;

        @Autowired
        private ReactiveRedisTemplate<String, String> redisTemplate;

        @Test
        @DisplayName("application context loads successfully with gateway starter")
        void contextLoads() {
            assertThat(context).isNotNull();
            assertThat(context.getStartupDate()).isPositive();
        }

        @Test
        @DisplayName("ReactiveRedisTemplate bean is created and connected")
        void redisTemplateIsAvailable() {
            assertThat(redisTemplate).isNotNull();
            assertThat(redisTemplate.getConnectionFactory()).isNotNull();
        }

        @Test
        @DisplayName("Redis container is running and reachable")
        void redisIsReachable() {
            Mono<String> ping = redisTemplate.opsForValue().getAndSet("__test_ping__", "pong");
            StepVerifier.create(ping)
                    .expectNextCount(1)
                    .verifyComplete();

            redisTemplate.delete("__test_ping__").block();
        }
    }

    // ---------- JWT nonce with real Redis ----------

    @Nested
    @DisplayName("JWT nonce validation")
    class JwtNonceValidation {

        @Autowired
        private JwtNonceValidator jwtNonceValidator;

        @Test
        @DisplayName("first nonce use succeeds")
        void firstNonceSucceeds() {
            StepVerifier.create(jwtNonceValidator.validate("session-1", "nonce-alpha"))
                    .verifyComplete();
        }

        @Test
        @DisplayName("replay of same nonce for same session fails with REPLAY_DETECTED")
        void replayDetected() {
            String sessionId = "session-2";
            String nonce = "nonce-replay";

            StepVerifier.create(jwtNonceValidator.validate(sessionId, nonce))
                    .verifyComplete();

            StepVerifier.create(jwtNonceValidator.validate(sessionId, nonce))
                    .verifyErrorSatisfies(e -> assertThat(e)
                            .isInstanceOf(JwtAuthenticationException.class)
                            .extracting("errorCode").isEqualTo(GatewayAuthErrorCode.REPLAY_DETECTED));
        }

        @Test
        @DisplayName("same nonce with different session succeeds")
        void sameNonceDifferentSession() {
            String nonce = "nonce-shared";

            StepVerifier.create(jwtNonceValidator.validate("session-3a", nonce))
                    .verifyComplete();

            StepVerifier.create(jwtNonceValidator.validate("session-3b", nonce))
                    .verifyComplete();
        }

        @Test
        @DisplayName("different nonces for same session all succeed")
        void differentNoncesSucceed() {
            StepVerifier.create(jwtNonceValidator.validate("session-4", "nonce-001"))
                    .verifyComplete();
            StepVerifier.create(jwtNonceValidator.validate("session-4", "nonce-002"))
                    .verifyComplete();
            StepVerifier.create(jwtNonceValidator.validate("session-4", "nonce-003"))
                    .verifyComplete();
        }
    }

    // ---------- HMAC nonce with real Redis ----------

    @Nested
    @DisplayName("HMAC nonce validation")
    class HmacNonceValidation {

        @Autowired
        private HmacNonceValidator hmacNonceValidator;

        @Test
        @DisplayName("first nonce use succeeds")
        void firstNonceSucceeds() {
            StepVerifier.create(hmacNonceValidator.validate("app-key-1", "hmac-nonce-alpha"))
                    .verifyComplete();
        }

        @Test
        @DisplayName("replay of same nonce for same app fails with REPLAY_DETECTED")
        void replayDetected() {
            String appKey = "app-key-2";
            String nonce = "hmac-nonce-replay";

            StepVerifier.create(hmacNonceValidator.validate(appKey, nonce))
                    .verifyComplete();

            StepVerifier.create(hmacNonceValidator.validate(appKey, nonce))
                    .verifyErrorSatisfies(e -> assertThat(e)
                            .isInstanceOf(JwtAuthenticationException.class)
                            .extracting("errorCode").isEqualTo(GatewayAuthErrorCode.REPLAY_DETECTED));
        }

        @Test
        @DisplayName("same nonce with different app key succeeds")
        void sameNonceDifferentApp() {
            String nonce = "hmac-nonce-cross-app";

            StepVerifier.create(hmacNonceValidator.validate("app-a", nonce))
                    .verifyComplete();

            StepVerifier.create(hmacNonceValidator.validate("app-b", nonce))
                    .verifyComplete();
        }
    }

    // ---------- JWT state validation with real Redis ----------

    @Nested
    @DisplayName("JWT state validation")
    class JwtStateValidation {

        @Autowired
        private JwtStateValidator jwtStateValidator;

        @Autowired
        private GatewaySecurityProperties properties;

        @Autowired
        private ReactiveRedisTemplate<String, String> redisTemplate;

        @Test
        @DisplayName("valid session passes validation")
        void validSessionPasses() {
            String sessionId = "valid-session";
            String sessionKey = properties.getJwt().getRedisKeys().getSessionPrefix() + sessionId;

            redisTemplate.opsForValue().set(sessionKey, "1").block();

            StepVerifier.create(jwtStateValidator.validate(sessionId, null, "user-ok"))
                    .verifyComplete();

            redisTemplate.delete(sessionKey).block();
        }

        @Test
        @DisplayName("missing session fails with SESSION_EXPIRED")
        void missingSessionFails() {
            StepVerifier.create(jwtStateValidator.validate("nonexistent-session", null, "user-ok"))
                    .verifyErrorSatisfies(e -> assertThat(e)
                            .isInstanceOf(JwtAuthenticationException.class)
                            .extracting("errorCode").isEqualTo(GatewayAuthErrorCode.SESSION_EXPIRED));
        }

        @Test
        @DisplayName("blacklisted token fails with TOKEN_BLACKLISTED")
        void blacklistedTokenFails() {
            String jti = "blacklisted-jti";
            String blacklistKey = properties.getJwt().getRedisKeys().getBlacklistPrefix() + jti;
            String sessionId = "session-for-blacklist";
            String sessionKey = properties.getJwt().getRedisKeys().getSessionPrefix() + sessionId;

            redisTemplate.opsForValue().set(sessionKey, "1").block();
            redisTemplate.opsForValue().set(blacklistKey, "1").block();

            StepVerifier.create(jwtStateValidator.validate(sessionId, jti, "user-ok"))
                    .verifyErrorSatisfies(e -> assertThat(e)
                            .isInstanceOf(JwtAuthenticationException.class)
                            .extracting("errorCode").isEqualTo(GatewayAuthErrorCode.TOKEN_BLACKLISTED));

            redisTemplate.delete(sessionKey).block();
            redisTemplate.delete(blacklistKey).block();
        }

        @Test
        @DisplayName("non-blacklisted token passes blacklist check")
        void nonBlacklistedTokenPasses() {
            String sessionId = "session-jti-ok";
            String sessionKey = properties.getJwt().getRedisKeys().getSessionPrefix() + sessionId;

            redisTemplate.opsForValue().set(sessionKey, "1").block();

            StepVerifier.create(jwtStateValidator.validate(sessionId, "clean-jti", "user-ok"))
                    .verifyComplete();

            redisTemplate.delete(sessionKey).block();
        }

        @Test
        @DisplayName("disabled user fails with USER_DISABLED")
        void disabledUserFails() {
            String sessionId = "session-disabled-user";
            String sessionKey = properties.getJwt().getRedisKeys().getSessionPrefix() + sessionId;
            String userKey = properties.getJwt().getRedisKeys().getUserEnabledPrefix() + "disabled-user";

            redisTemplate.opsForValue().set(sessionKey, "1").block();
            redisTemplate.opsForValue().set(userKey, "DISABLED").block();

            StepVerifier.create(jwtStateValidator.validate(sessionId, null, "disabled-user"))
                    .verifyErrorSatisfies(e -> assertThat(e)
                            .isInstanceOf(JwtAuthenticationException.class)
                            .extracting("errorCode").isEqualTo(GatewayAuthErrorCode.USER_DISABLED));

            redisTemplate.delete(sessionKey).block();
            redisTemplate.delete(userKey).block();
        }

        @Test
        @DisplayName("enabled user (non-disabled value) passes")
        void enabledUserPasses() {
            String sessionId = "session-enabled-user";
            String sessionKey = properties.getJwt().getRedisKeys().getSessionPrefix() + sessionId;
            String userKey = properties.getJwt().getRedisKeys().getUserEnabledPrefix() + "enabled-user";

            redisTemplate.opsForValue().set(sessionKey, "1").block();
            redisTemplate.opsForValue().set(userKey, "1").block();

            StepVerifier.create(jwtStateValidator.validate(sessionId, null, "enabled-user"))
                    .verifyComplete();

            redisTemplate.delete(sessionKey).block();
            redisTemplate.delete(userKey).block();
        }

        @Test
        @DisplayName("user not in Redis passes (key absent)")
        void userNotInRedisPasses() {
            String sessionId = "session-no-user-key";
            String sessionKey = properties.getJwt().getRedisKeys().getSessionPrefix() + sessionId;

            redisTemplate.opsForValue().set(sessionKey, "1").block();

            StepVerifier.create(jwtStateValidator.validate(sessionId, null, "unknown-user"))
                    .verifyComplete();

            redisTemplate.delete(sessionKey).block();
        }

        @Test
        @DisplayName("null jti skips blacklist check and passes")
        void nullJtiSkipsBlacklist() {
            String sessionId = "session-null-jti";
            String sessionKey = properties.getJwt().getRedisKeys().getSessionPrefix() + sessionId;

            redisTemplate.opsForValue().set(sessionKey, "1").block();

            StepVerifier.create(jwtStateValidator.validate(sessionId, null, "user-ok"))
                    .verifyComplete();

            redisTemplate.delete(sessionKey).block();
        }
    }

    // ---------- app credential resolution ----------

    @Nested
    @DisplayName("App credential resolution")
    class AppCredentialResolution {

        @Autowired
        private DefaultAppCredentialResolver resolver;

        @Autowired
        private GatewaySecurityProperties properties;

        @Autowired
        private ReactiveRedisTemplate<String, String> redisTemplate;

        @Test
        @DisplayName("resolves app from Redis hash")
        void resolvesFromRedis() {
            String appKey = "redis-app-001";
            String redisKey = properties.getHmac().getCredentials().getRedisKeyPrefix() + appKey;

            redisTemplate.opsForHash().putAll(redisKey, Map.of(
                    "appSecret", "redis-app-secret",
                    "appCode", "redis-app-code",
                    "appId", "redis-app-id",
                    "tenantId", "tenant-redis",
                    "tenantCode", "TR001",
                    "permissions", "read,write",
                    "isEnabled", "true"
            )).block();

            StepVerifier.create(resolver.resolve(appKey))
                    .assertNext(credential -> {
                        assertThat(credential.getAppKey()).isEqualTo(appKey);
                        assertThat(credential.getAppSecret()).isEqualTo("redis-app-secret");
                        assertThat(credential.getAppCode()).isEqualTo("redis-app-code");
                        assertThat(credential.getAppId()).isEqualTo("redis-app-id");
                        assertThat(credential.getTenantId()).isEqualTo("tenant-redis");
                        assertThat(credential.getTenantCode()).isEqualTo("TR001");
                        assertThat(credential.getPermissions()).containsExactly("read", "write");
                        assertThat(credential.isEnabled()).isTrue();
                    })
                    .verifyComplete();

            redisTemplate.delete(redisKey).block();
        }

        @Test
        @DisplayName("disabled app in Redis returns APP_DISABLED")
        void disabledAppInRedis() {
            String appKey = "redis-disabled-app";
            String redisKey = properties.getHmac().getCredentials().getRedisKeyPrefix() + appKey;

            redisTemplate.opsForHash().putAll(redisKey, Map.of(
                    "appSecret", "secret",
                    "appCode", "code",
                    "isEnabled", "false"
            )).block();

            StepVerifier.create(resolver.resolve(appKey))
                    .verifyErrorSatisfies(e -> assertThat(e)
                            .isInstanceOf(JwtAuthenticationException.class)
                            .extracting("errorCode").isEqualTo(GatewayAuthErrorCode.APP_DISABLED));

            redisTemplate.delete(redisKey).block();
        }

        @Test
        @DisplayName("unknown app from Redis falls back to config")
        void fallsBackToConfig() {
            StepVerifier.create(resolver.resolve("test-app"))
                    .assertNext(credential -> {
                        assertThat(credential.getAppKey()).isEqualTo("test-app");
                        assertThat(credential.getAppSecret()).isEqualTo("test-secret");
                        assertThat(credential.getAppCode()).isEqualTo("test-app-code");
                    })
                    .verifyComplete();
        }

        @Test
        @DisplayName("completely unknown app returns UNKNOWN_APP")
        void unknownApp() {
            StepVerifier.create(resolver.resolve("nonexistent-app"))
                    .verifyErrorSatisfies(e -> assertThat(e)
                            .isInstanceOf(JwtAuthenticationException.class)
                            .extracting("errorCode").isEqualTo(GatewayAuthErrorCode.UNKNOWN_APP));
        }

        @Test
        @DisplayName("app in config but disabled returns APP_DISABLED")
        void disabledAppInConfig() {
            GatewaySecurityProperties.ConfigApp disabledApp = new GatewaySecurityProperties.ConfigApp();
            disabledApp.setAppKey("disabled-config-app");
            disabledApp.setAppSecret("secret");
            disabledApp.setAppCode("code");
            disabledApp.setEnabled(false);
            properties.getHmac().getCredentials().getApps().add(disabledApp);

            StepVerifier.create(resolver.resolve("disabled-config-app"))
                    .verifyErrorSatisfies(e -> assertThat(e)
                            .isInstanceOf(JwtAuthenticationException.class)
                            .extracting("errorCode").isEqualTo(GatewayAuthErrorCode.APP_DISABLED));
        }
    }

    // ---------- nonce TTL verification ----------

    @Nested
    @DisplayName("Nonce TTL verification")
    class NonceTtl {

        @Autowired
        private ReactiveRedisTemplate<String, String> redisTemplate;

        @Test
        @DisplayName("TTL is set on nonce keys via SETNX")
        void nonceKeysHaveTtl() {
            String testKey = "platform:gateway:jwt:nonce:ttl-test:test-nonce";
            redisTemplate.opsForValue().setIfAbsent(testKey, "1",
                    java.time.Duration.ofSeconds(60)).block();

            Long ttl = redisTemplate.getExpire(testKey).block();
            assertThat(ttl).isNotNull();
            assertThat(ttl).isPositive();

            redisTemplate.delete(testKey).block();
        }
    }

    // ---------- Route policy resolver: all four modes ----------

    @Nested
    @DisplayName("Route policy resolution (4 auth modes)")
    class RoutePolicyModes {

        @Autowired
        private RouteSecurityPolicyResolver policyResolver;

        @Test
        @DisplayName("NONE auth mode on default path (no routes configured)")
        void noneMode() {
            RouteSecurityPolicy policy = policyResolver.resolve("/some/path", "GET");
            assertThat(policy).isNotNull();
            assertThat(policy.getAuthMode()).isEqualTo(AuthMode.NONE);
        }

        @Test
        @DisplayName("JWT auth mode via programmatic route policy")
        void jwtMode() {
            GatewaySecurityProperties props = new GatewaySecurityProperties();
            props.setDefaultAuthMode(AuthMode.NONE);
            props.getPublicPaths().add("/public/**");

            RouteSecurityPolicyResolver r = new RouteSecurityPolicyResolver(props);
            r.addRoutePolicy("jwt-route", java.util.List.of("/api/**"), java.util.List.of(), AuthMode.JWT);
            r.afterPropertiesSet();

            RouteSecurityPolicy policy = r.resolve("/api/data", "POST");
            assertThat(policy.getAuthMode()).isEqualTo(AuthMode.JWT);
            assertThat(policy.getMatchedRuleId()).isEqualTo("jwt-route");
        }

        @Test
        @DisplayName("HMAC auth mode via programmatic route policy")
        void hmacMode() {
            GatewaySecurityProperties props = new GatewaySecurityProperties();
            props.setDefaultAuthMode(AuthMode.NONE);

            RouteSecurityPolicyResolver r = new RouteSecurityPolicyResolver(props);
            r.addRoutePolicy("hmac-route", java.util.List.of("/openapi/**"), java.util.List.of(), AuthMode.HMAC);
            r.afterPropertiesSet();

            RouteSecurityPolicy policy = r.resolve("/openapi/data", "GET");
            assertThat(policy.getAuthMode()).isEqualTo(AuthMode.HMAC);
        }

        @Test
        @DisplayName("JWT_OR_HMAC auth mode via programmatic route policy")
        void jwtOrHmacMode() {
            GatewaySecurityProperties props = new GatewaySecurityProperties();
            props.setDefaultAuthMode(AuthMode.NONE);

            RouteSecurityPolicyResolver r = new RouteSecurityPolicyResolver(props);
            r.addRoutePolicy("dual-route", java.util.List.of("/dual/**"), java.util.List.of(), AuthMode.JWT_OR_HMAC);
            r.afterPropertiesSet();

            RouteSecurityPolicy policy = r.resolve("/dual/resource", "POST");
            assertThat(policy.getAuthMode()).isEqualTo(AuthMode.JWT_OR_HMAC);
        }

        @Test
        @DisplayName("default auth mode is NONE (none/jwt/hmac/jwt-or-hmac all supported)")
        void defaultModeIsNone() {
            assertThat(policyResolver.getDefaultAuthMode()).isEqualTo(AuthMode.NONE);
        }
    }
}

